import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>给照片加圆角只要几分钟。上传图片，拖一下滑块定好弧度，下载下来就是柔和的成品。</p>\n<p>这篇教程会一步步带你走完整个流程。包括半径滑块、单个圆角控制、整圆快捷按钮、填充选择，以及能保住透明角的导出格式。</p>\n<p>看完你就能在任何设备上做出圆角头像、卡片图或者胶囊形横幅。确认成品之前，先别删原图。</p>\n<h2 id=\"before-you-start\">开始之前：先定好要什么形状</h2>\n<p>打开工具之前，先想好要什么形状。圆形适合头像，轻微圆角适合卡片，胶囊形适合横幅和徽章。</p>\n<p>再看一眼用途。头像框可能要求圆形，博客卡片可能只需要上面两个角变圆。</p>\n<p>用原图，别用压缩过的副本。原图够清晰，曲线边缘才光滑；拿发软的副本做圆角，弧线会显得粗糙。</p>\n<p>在浏览器里打开<a href=\"/zh/yuanjiao-tupian/\">图片圆角工具</a>。全部处理都在本地完成，照片不会上传到服务器。</p>\n<h2 id=\"step-by-step\">5步给图片加圆角</h2>\n<p>轻微圆角和整圆的流程完全一样。上传、设半径、选填充、检查预览、下载。</p>\n<p>调半径时别着急。数值差一点，形状的感觉可能差很多，拖动时盯着预览看。</p>\n<ol>\n<li>把图片拖进上传区，或者从设备里选择，也可以直接用 Ctrl+V 粘贴截图。</li>\n<li>拖动“全部圆角半径”滑块定好弧度，旁边会实时显示像素数值。</li>\n<li>打开单个圆角模式可以分别设四个角，或者用“整圆 / 胶囊形”快捷按钮一键成形。</li>\n<li>在“外角填充”里选“透明”，角落就是通透的；选“纯色”，角落会被填上颜色。</li>\n<li>选导出格式，想保住透明就用 PNG 或 WebP，然后点“下载”保存成品。</li>\n</ol>\n<p>用之前先打开下载好的文件看一眼。确认四个角光滑、没有重要内容被切掉。</p>\n<h2 id=\"setting-radius\">圆角半径怎么调</h2>\n<p>半径滑块控制圆角有多圆。数值小只是轻轻柔化，数值大，四个角会弯成很深的弧线。</p>\n<p>10 到 20 像素适合卡片、缩略图和截图。圆角很含蓄，图片看着还是矩形，只是边角变软了。</p>\n<p>50 到 100 像素的圆角一眼就能看出来。适合头像、社交帖子和 App 配图，形状本身就是设计的一部分。</p>\n<p>滑块旁边会实时显示精确的像素值。记下这个数值，以后给别的图做同样的圆角，直接照着设就行。</p>\n<h2 id=\"per-corner-mode\">单个圆角模式怎么用</h2>\n<p>单个圆角模式可以给每个角单独设半径。打开后会出现四个滑块，图片的每个角各对应一个。</p>\n<p>博客卡片是最典型的用法。上面两个角变圆，下面两个角保持直角，照片就能稳稳地嵌在卡片顶部。</p>\n<p>关掉这个模式，会回到四个角统一半径。关掉期间单独设好的数值会保留，重新打开也不用重设。</p>\n<p>单个圆角别乱用。四个角半径各不相同，看起来像失误；只圆一两个角、其余保持直角，反而显得是刻意设计。</p>\n<h2 id=\"full-circle-shortcut\">“整圆 / 胶囊形”快捷按钮怎么用</h2>\n<p>点一下“整圆”快捷按钮，半径立刻变成图片边长的一半。正方形照片变成完美的圆形，长方形照片变成胶囊形。</p>\n<p>想要干净的圆形，先把照片裁成 1:1。正方形原图加这个按钮，就是能放进任何头像框的圆形头像。</p>\n<p>长方形照片用这个按钮，会得到两端完全圆润的胶囊形。胶囊形适合按钮、徽章和横幅。</p>\n<p>下载之前先检查成品。胶囊形可以很优雅，但宽幅照片的两侧内容也可能被裁掉不少。</p>\n<h2 id=\"choosing-fill\">透明还是纯色填充，怎么选</h2>\n<p>角落切掉之后，空出来的地方总得填点什么。透明是让角落透出底下的内容，纯色是用一种颜色填满。</p>\n<p>网页配图、头像和叠加图层选透明。图片能融入任何背景，因为角落显示的是图片后面的东西。</p>\n<p>目的地不支持透明时选纯色。比如白色填充，图片看着像一张圆角照片贴在白卡上，适合文档和打印。</p>\n<p>如果选了 JPG 又点了透明，工具会自动切换格式。JPG 没有透明通道，所以会帮你换成 PNG 或 WebP。</p>\n<h2 id=\"choosing-format\">导出格式怎么选</h2>\n<p>想要最清晰又带透明的效果，选 PNG。它是无损格式，曲线边缘始终平滑，而且到处都能打开，包括老浏览器。</p>\n<p>想要文件小一点又带透明，选 WebP。同样是通透的角落，文件比 PNG 小得多，只是少数老系统还不认这个格式。</p>\n<p>只有角落填了纯色时，才考虑 JPG。JPG 没有透明通道，透明导出成 JPG 会被填成纯色，可能和你的背景对不上。</p>\n<p>网页上的圆角图形，用 PNG 或 WebP 就对了。白底页面上的圆角照片，JPG 配白色填充也完全够用。</p>\n<h2 id=\"previewing\">下载之前先预览</h2>\n<p>下载之前一定要预览。确认四个角光滑、半径感觉对、没有重要内容被切掉。</p>\n<p>放大看一个角，检查弧线。平滑的弧线说明圆角做得很好，锯齿状的边缘说明原图太小或者太软。</p>\n<p>再看一眼填充色和图片最终所在的背景搭不搭。透明角放哪都合适，纯色填充只和设定的那个颜色搭。</p>\n<p>半径感觉不对就再调一下滑块。数值差一点，形状的感觉可能差很多。</p>\n<h2 id=\"rounding-for-avatar\">头像的圆角怎么做</h2>\n<p>先用<a href=\"/zh/caijian-tupian/\">图片裁剪工具</a>把照片裁成正方形。1:1 裁剪、人脸居中，是圆形头像最好的起点。</p>\n<p>上传正方形照片，点一下“整圆”快捷按钮。半径跳到图片边长的一半，照片立刻变成完美的圆形。</p>\n<p>人脸要尽量留在画面中间。角落会被切掉，脸太靠边的话，耳朵或者一部分头发会被弧线裁掉。</p>\n<p>导出成 PNG 或 WebP。透明角能让头像融入任何资料背景，不管浅色还是深色都好看。</p>\n<h2 id=\"rounding-for-cards\">卡片和界面配图的圆角怎么做</h2>\n<p>照片半径要和卡片半径一致。16 像素的照片放进 16 像素的卡片里天衣无缝，半径对不上就显得很随意。</p>\n<p>博客卡片只圆上面两个角，下面两个留直角。打开单个圆角模式，设好上面两个角的半径，下面两个留 0。</p>\n<p>同一组卡片的半径要统一。一排圆角一致的卡片看着很专业，半径各不相同就显得杂乱。</p>\n<p>卡片放在彩色背景上时，卡片图导出成 PNG 或 WebP。透明角在任何颜色上都干净。</p>\n<h2 id=\"rounding-screenshots\">截图的圆角怎么做</h2>\n<p>直接用 Ctrl+V 粘贴截图，省掉先保存再上传的步骤。图片立刻出现在工具里，就可以开始加圆角。</p>\n<p>截图用 10 到 20 像素的小半径。轻轻柔化一下，就有了现代 App 卡片的感觉，还不会遮住任何内容。</p>\n<p>圆角截图导出成 PNG。无损格式能让小字保持清晰，截图里是设置项或者报错信息时，这一点很重要。</p>\n<p>同一篇教程里的截图，半径要统一。圆角一致，读者跟着步骤走更顺；半径各不相同，反而分散注意力。</p>\n<h2 id=\"rounding-on-mobile\">手机和平板上怎么加圆角</h2>\n<p>工具支持触屏，拍照的手机就能直接修图。从相册上传，手指拖动半径滑块，下载成品就行。</p>\n<p>手机上做头像，直接用“整圆”快捷按钮。点一下，正方形照片就变成圆形，比在小屏幕上慢慢拖滑块快得多。</p>\n<p>下载之前先全尺寸看一眼预览。小手机屏幕上看着柔和的半径，放到电脑上可能明显得多。</p>\n<p>下载的文件会保存在常用的下载文件夹里。之后可以直接设为头像，或者直接分享出去。</p>\n<h2 id=\"troubleshooting\">圆角常见问题怎么解决</h2>\n<p>角落显示白色背景而不是透明，先检查导出格式。JPG 没有透明通道，改成 PNG 或 WebP 导出，角落就能保持通透。</p>\n<p>做出来是胶囊形而不是圆形，说明原图是长方形的。先裁成正方形，再用“整圆”快捷按钮。</p>\n<p>角落看着有锯齿，可能是原图分辨率太低。换一张更高清的原图，曲线就能渲染得平滑。</p>\n<p>单个圆角的数值找不到了，先看是不是关掉了这个模式。数值在模式关闭期间会保留，重新打开就能恢复。</p>\n<h2 id=\"combining-with-border\">圆角加边框怎么做</h2>\n<p>先加圆角，再用<a href=\"/zh/tupian-biankuang-shengcheng/\">图片边框生成器</a>加边框。边框工具会读取图片的形状，先圆角能让边框和弧线对得严丝合缝。</p>\n<p>边框半径要和圆角半径一致。16 像素的边框配 16 像素的圆角，看着天衣无缝。</p>\n<p>想要卡片效果，用细边框配柔和的半径。这个组合很像现代 App 卡片，适合社交帖子和演示文稿。</p>\n<p>拍立得风格要保持直角。经典即时成像照片就是尖角，圆角反而破坏了那种复古感。</p>\n<h2 id=\"quick-tips\">圆角做得更好的几个小技巧</h2>\n<p>加圆角之前先裁好形状。圆形要正方形裁剪，胶囊形要宽幅裁剪，博客图要卡片比例裁剪，都从裁剪开始。</p>\n<p>下载之前全尺寸预览一遍。放大看四个角，确认曲线光滑、没有重要内容被切掉。</p>\n<p>保存时起个清楚的名字，比如 avatar-circle.png。以后还要用同样的形状，清楚的名字能省下重做的时间。</p>\n<p>原图一定要留好。一旦导出成圆角图，被切掉的角落就再也找不回来了。</p>\n<h2 id=\"rounding-for-social-post\">社交帖子的圆角怎么做</h2>\n<p>社交帖子带圆角，看着更现代、更友好。柔和的边缘和 App 里的卡片、按钮是一个风格，图片能自然融入界面。</p>\n<p>信息流帖子用小到中等半径。10 到 20 像素的轻微圆角就够了，既柔和了图片，又不改变内容、不遮挡画面。</p>\n<p>同一账号的帖子，半径要统一。每张图的圆角形状都一样，整个主页看着像精心打理过；半径各不相同就显得杂乱。</p>\n<p>角落填了纯色就导出 JPG，角落透明就导出 PNG 或 WebP。格式选对了，角落在任何背景上都干净。</p>\n<h2 id=\"rounding-for-presentation\">演示文稿里的图片怎么做圆角</h2>\n<p>幻灯片上的照片带圆角更好看。柔和的边缘和现代幻灯片设计是一个风格，图片像是特意放上去的元素，而不是随便粘贴的矩形。</p>\n<p>照片半径要和幻灯片主题对上。整套幻灯片卡片是 16 像素圆角，照片也用 16 像素，图片和卡片才能对齐。</p>\n<p>投影放大的幻灯片，半径别太大。巨幕上的大半径会喧宾夺主，轻微圆角在任何尺寸下都很含蓄。</p>\n<p>角落填了纯色时，演示图片导出 JPG，用高质量设置。投影时照片要保持清晰，低质量导出会让曲线发软。</p>\n<p>想对比两种形状，请读<a href=\"/zh/blog/yuanjiao-haishi-yuanxing-caijian/\">圆角和圆形裁剪哪个好？头像与卡片这样选</a>。想看完整指南，请读<a href=\"/zh/blog/tupian-yuanjiao-zhinan/\">图片圆角完全指南：半径、透明底与导出格式全讲清</a>；想给圆角照片加边框，可以试试<a href=\"/zh/tupian-biankuang-shengcheng/\">图片边框生成器</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"手机上怎么给照片加圆角？","answer":"在手机浏览器里打开图片圆角工具，从相册上传照片，手指拖动半径滑块就行。做圆形头像直接点“整圆”快捷按钮。导出成 PNG 或 WebP，角落才能保持透明。"},{"question":"卡片图用多大的圆角半径合适？","answer":"大多数卡片用 10 到 20 像素的小到中等半径，轻轻柔化一下就好，不会改变图片形状。照片半径要和卡片半径一致，看着才严丝合缝。博客卡片可以只圆上面两个角，下面两个留直角。"},{"question":"JPG 图片能不能加圆角？","answer":"可以，但角落会被填成纯色，因为 JPG 没有透明通道。填充色要和图片最终所在的背景一致；想让角落通透，就导出成 PNG 或 WebP。"},{"question":"换一张图会丢掉已经设好的半径吗？","answer":"不会。用工具里的替换选项换图，当前的半径和填充设置会保留。换好之后再根据新照片微调一下半径，就能用同样的设置导出。"},{"question":"为什么我的圆角看着有锯齿？","answer":"原图可能太小或者太软，曲线渲染出来就成了看得见的台阶。换一张更高清的原图，边缘就会光滑。导出成 PNG 也有帮助，因为它是无损格式。"},{"question":"加圆角会改变照片的宽和高吗？","answer":"不会。圆角只切掉四个角的部分，宽和高保持不变。文件还是原来的像素尺寸，角落要么透明，要么填上纯色。"}];
